package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Component;
import org.w3c.dom.Element;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Qimen white paper 5.13-5.15, 5.32: stockout CGTH, never a sales deliveryorder. */
@Component public class QimenStockoutProtocol {
 private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
 private String v(Element e,String key){Element child=e==null?null:QimenProtocol.child(e,key);return child==null?"":child.getTextContent().trim();}
 private String enc(String s){try{return java.net.URLEncoder.encode(s,"UTF-8");}catch(Exception e){throw new IllegalArgumentException(e);}}
 private long qty(String value){try{long n=new java.math.BigDecimal(value).longValueExact();require(n>=0&&n<=100000000,"出库数量无效");return n;}catch(Exception e){throw new IllegalArgumentException("出库数量须为非负整数");}}
 public String type(String raw){require(Arrays.asList("","ZP","CC").contains(raw),"本轮采购退仓仅接收ZP正品和CC次品，请核对仓库质量编码");return raw.equals("CC")?"CP":"ZP";}
 @SuppressWarnings("unchecked") public WmsProtocol.Wire request(Map<String,Object> c,String secret,String action,Map<String,Object> d,Map<String,Object> payload){
  require("QIMEN".equals(c.get("provider"))&&"2.0".equals(text(c.get("api_version"))),"采购退仓本轮接入奇门2.0 stockout接口");Map<String,Object> route=(Map<String,Object>)payload.get("route");Map<String,Object> req;
  if(action.equals("CREATE")){Map<String,Object> h=map("deliveryOrderCode",d.get("return_sn"),"orderType","CGTH","warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),"createTime",payload.get("create_time"),"supplierCode",d.get("supplier_sn"),"supplierName",d.get("supplier_name"),"logisticsCode",d.get("carrier_code"),"transportMode","快递","receiverInfo",payload.get("receiver"),"remark",d.get("reason"),"totalOrderLines",((List<?>)payload.get("lines")).size());h.put("relatedOrders",map("relatedOrder",map("orderType","CG","orderCode",d.get("po_sn"))));List<Map<String,Object>> lines=new ArrayList<>();for(Map<String,Object> l:(List<Map<String,Object>>)payload.get("lines"))lines.add(map("orderLineNo",l.get("id"),"ownerCode",route.get("external_owner"),"itemCode",l.get("sku_sn"),"itemName",l.get("goods_name"),"inventoryType","CP".equals(l.get("inventory_type"))?"CC":"ZP","planQty",l.get("quantity"),"batchCode",l.get("batch_code"),"purchaseReturnPrice",l.get("purchase_price")));req=map("deliveryOrder",h,"orderLines",lines);
  }else if(action.equals("QUERY"))req=map("ownerCode",route.get("external_owner"),"warehouseCode",route.get("external_warehouse"),"deliveryOrderCode",d.get("return_sn"),"deliveryOrderId",d.get("external_order"),"page",1,"pageSize",100);
  else{require(action.equals("CANCEL"),"未知采购退仓动作");req=map("ownerCode",route.get("external_owner"),"warehouseCode",route.get("external_warehouse"),"orderCode",d.get("return_sn"),"orderId",d.get("external_order"),"orderType","CGTH","cancelReason",d.get("cancel_reason"));}
  String body=WmsOutboundPayload.xml(req);Map<String,String> p=new TreeMap<>();p.put("app_key",text(c.get("app_key")));p.put("customerId",text(c.get("customer_id")));p.put("method","taobao.qimen."+(action.equals("CANCEL")?"order.cancel":"stockout."+(action.equals("CREATE")?"create":"query")));p.put("format","xml");p.put("sign_method","md5");p.put("v","2.0");p.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(TIME));p.put("sign",QimenProtocol.sign(p,body,secret));return new WmsProtocol.Wire(text(c.get("endpoint"))+"?"+p.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).collect(Collectors.joining("&")),body,"application/xml;charset=UTF-8");
 }
 public WmsProtocol.Reply reply(String action,String body){return new QimenProtocol().outboundReply(action,body);}
 public Map<String,Object> callback(Map<String,Object> c,String secret,Map<String,String> p,String body){return parse(c,secret,p,body,false);}
 public Map<String,Object> part(Map<String,Object> c,String secret,Map<String,String> p,String body){return parse(c,secret,p,body,true);}
 private Map<String,Object> parse(Map<String,Object> c,String secret,Map<String,String> p,String body,boolean fragmented){require(Arrays.asList("taobao.qimen.stockout.confirm","stockout.confirm").contains(p.get("method"))&&"2.0".equals(p.get("v"))&&"2.0".equals(text(c.get("api_version")))&&"md5".equals(p.get("sign_method")),"采购退仓回传方法或版本不匹配");require(text(c.get("app_key")).equals(p.get("app_key"))&&text(c.get("customer_id")).equals(p.get("customerId")),"回传应用不匹配");LocalDateTime sent;try{sent=LocalDateTime.parse(p.get("timestamp"),TIME);}catch(Exception e){throw new IllegalArgumentException("回传时间格式无效");}require(Math.abs(Duration.between(sent,LocalDateTime.now(ZoneId.of("Asia/Shanghai"))).getSeconds())<=600,"回传时间超出允许范围");require(java.security.MessageDigest.isEqual(QimenProtocol.sign(p,body,secret).getBytes(StandardCharsets.UTF_8),text(p.get("sign")).getBytes(StandardCharsets.UTF_8)),"采购退仓回传验签失败");Element root=QimenProtocol.parse(body),h=QimenProtocol.child(root,"deliveryOrder");require(h!=null&&"request".equals(root.getTagName())&&"CGTH".equals(v(h,"orderType")),"采购退仓必须使用CGTH出库确认报文");String status=v(h,"status"),confirm=v(h,"confirmType"),msg=v(h,"outBizCode");require(Arrays.asList("PARTDELIVERED","DELIVERED").contains(status)&&Arrays.asList("","0","1").contains(confirm),"请回传实际出库及最终/中间确认类型");boolean complete=confirm.equals("0")||confirm.isEmpty()&&status.equals("DELIVERED");require(!status.equals("DELIVERED")||complete,"最终状态和确认类型矛盾");if(msg.isEmpty()){require(complete,"多次出库必须提供唯一outBizCode");msg="FINAL";}require(msg.length()<=128,"消息ID过长");String time=v(h,"orderConfirmTime");if(!time.isEmpty())try{LocalDateTime.parse(time,TIME);}catch(Exception e){throw new IllegalArgumentException("实际出库时间无效");}List<Map<String,Object>> lines=new ArrayList<>();int count=0;Element group=QimenProtocol.child(root,"orderLines");if(group!=null)for(Element l:QimenProtocol.children(group,"orderLine")){count++;String no=v(l,"orderLineNo"),sku=v(l,"itemCode"),owner=v(l,"ownerCode");long actual=qty(v(l,"actualQty"));Element batches=QimenProtocol.child(l,"batchs");List<Element> bs=batches==null?Collections.emptyList():QimenProtocol.children(batches,"batch");if(bs.isEmpty())lines.add(map("line_key",no,"sku_sn",sku,"owner_code",owner,"batch_code",v(l,"batchCode"),"inventory_type",type(v(l,"inventoryType")),"quantity",actual));else{long sum=0;for(Element b:bs){long q=qty(v(b,"actualQty"));sum=Math.addExact(sum,q);lines.add(map("line_key",no,"sku_sn",sku,"owner_code",owner,"batch_code",v(b,"batchCode"),"inventory_type",type(v(b,"inventoryType")),"quantity",q));}require(sum==actual,"批次出库数量与原商品行不一致");}}
  require(lines.size()<=200&&(!lines.isEmpty()||complete),"采购退仓回传明细数量无效");long total=v(h,"totalOrderLines").isEmpty()?count:qty(v(h,"totalOrderLines"));require(total>=count&&total<=200,"声明明细数量无效");if(!fragmented)require(total==count,"回传明细尚未完整，不能扣账");List<Map<String,Object>> packages=new ArrayList<>();Element ps=QimenProtocol.child(root,"packages");if(ps!=null)for(Element pack:QimenProtocol.children(ps,"package")){List<Map<String,Object>>items=new ArrayList<>();String error="";Element raw=QimenProtocol.child(pack,"items");if(raw!=null)for(Element item:QimenProtocol.children(raw,"item")){try{long q=qty(v(item,"quantity"));require(q>0&&!v(item,"itemCode").isEmpty(),"包裹SKU或数量无效");String hint=v(item,"inventoryType");require(Arrays.asList("","ZP","CC").contains(hint),"包裹质量需要核对");items.add(map("sku_sn",v(item,"itemCode"),"quantity",q,"line_key",v(item,"orderLineNo"),"batch_code",v(item,"batchCode"),"inventory_type",hint.equals("CC")?"CP":hint));}catch(IllegalArgumentException e){error="包裹商品内容无效，待仓库补齐";}}require(items.size()<=1000,"包裹商品超过上限");packages.add(map("package_code",v(pack,"packageCode"),"carrier_code",v(pack,"logisticsCode"),"carrier_name",v(pack,"logisticsName"),"waybill",v(pack,"expressCode"),"items",items,"parse_error",error));}require(packages.size()<=100,"回传包裹数量超过限制");return map("return_sn",v(h,"deliveryOrderCode"),"external_order",v(h,"deliveryOrderId"),"owner_code",v(h,"ownerCode"),"warehouse_code",v(h,"warehouseCode"),"message_id",msg,"complete",complete,"status",status,"outbound_time",time,"carrier_code",v(h,"logisticsCode"),"carrier_name",v(h,"logisticsName"),"waybill",v(h,"expressCode"),"packages",packages,"lines",lines,"total_lines",total,"source_lines",count,"snapshot_version",v(QimenProtocol.child(h,"extendProps"),"omsSnapshotVersion"));
 }
}
